window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[100]={"id":"100","numero":100,"titre":"Céphalée aiguë et chronique","objectifs":[{"id":"100-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une céphalée aiguë et d’une céphalée chronique","contenu":"<div class=\"notion-course\"><h4>Partir de l’histoire, pas seulement de l’intensité</h4><p>Une céphalée est une douleur de l’extrémité céphalique. Le diagnostic distingue une maladie primaire (migraine, céphalée de tension, <span class=\"nc-orange_bg\">algie vasculaire de la face</span>) d’une douleur secondaire à une affection locale ou générale. Un examen neurologique normal ne suffit pas à exclure une cause grave.</p><table><thead><tr><th>Question</th><th>Ce qu’elle change</th></tr></thead><tbody><tr><td>Déjà eu exactement la même douleur ?</td><td>Ancienne et habituelle : rechercher un phénotype primaire. Nouvelle, différente ou récemment aggravée : chercher une cause secondaire.</td></tr><tr><td>Depuis quand ? En combien de temps a-t-elle été maximale ?</td><td>Distinguer début instantané ou rapide, progression sur des jours, crises répétées et fond permanent. Un coup de tonnerre atteint son maximum en moins d’une minute.</td></tr><tr><td>Durée de chaque épisode et nombre de jours par mois ?</td><td>Différencier migraine, tension, algies brèves et <span class=\"nc-yellow_bg\">céphalée chronique</span> quotidienne ; compter aussi les jours de prise médicamenteuse.</td></tr><tr><td>Circonstances et signes associés ?</td><td><span class=\"nc-red nc-bold\">Effort</span>, <span class=\"nc-red nc-bold\">activité sexuelle</span>, toux/<span class=\"nc-red nc-bold\">Valsalva</span>, posture, traumatisme, geste dural ; fièvre, <span class=\"nc-blue_bg\">vomissements</span>, troubles visuels, déficit ou crise épileptique.</td></tr><tr><td>Terrain et retentissement ?</td><td>Âge, grossesse/<span class=\"nc-red_bg\">post-partum</span>, cancer, <span class=\"nc-orange\">immunodépression</span>, anticoagulant, produits vasoactifs ; sommeil, scolarité, travail et handicap.</td></tr></tbody></table><h4>Examen minimal</h4><ul><li>Constantes : température, pression artérielle, vigilance ; examiner la peau à la recherche d’un purpura.</li><li>Examen neurologique complet, raideur méningée, pupilles et oculomotricité ; fond d’œil pour l’œdème papillaire.</li><li>Examen oculaire et ORL ; artères temporales après 50 ans ; recherche d’une douleur cervicale et d’un contexte toxique.</li></ul><div class=\"callout\"><p>« Aiguë » signifie ici <span class=\"nc-red\">récente</span> et <span class=\"nc-red\">inhabituelle</span> : ne pas rendre une céphalée rassurante parce qu’elle dure depuis plus de sept jours. « Chronique » décrit une durée ou une fréquence ; ce mot n’établit pas à lui seul la bénignité.</p></div><details><summary>Repères d’innervation sensitive</summary><table><thead><tr><th>Nerf</th><th>Territoire utile</th></tr></thead><tbody><tr><td>V1</td><td>Front, cornée, <span class=\"nc-blue_bg\">paupière supérieure</span> et dos du nez.</td></tr><tr><td>V2</td><td>Joue haute, aile du nez, lèvre et arcade dentaire supérieures.</td></tr><tr><td>V3</td><td>Menton, lèvre et arcade inférieures ; sensibilité générale des deux tiers antérieurs de la langue. Motricité masticatrice.</td></tr><tr><td>VII bis</td><td>Petite zone auriculaire de Ramsay-Hunt ; goût des deux tiers antérieurs de la langue, distinct de la sensibilité du V3.</td></tr><tr><td>Racines cervicales supérieures</td><td>Région occipitale et partie inférieure du pavillon ; convergence trigémino-cervicale.</td></tr></tbody></table></details></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p>Suppression d’un seuil de sept jours utilisé comme définition absolue et correction des fractions mal encodées.</p></details><details><summary>Situations de départ LiSA vérifiées</summary><ul><li><a href=\"https://livret.uness.fr/lisa/2026/C%C3%A9phal%C3%A9e_SDD-118\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 118 · Céphalée</a><ul><li>Caractériser douleur, chronologie et déclencheurs ; agenda et retentissement.</li><li>Reconnaître urgence ; justifier imagerie et PL ; expliquer traitement et prévention.</li></ul></li></ul><p>Pages et attendus consultés directement sur LiSA 2026 le 13 octobre 2026. Les arbres sont des synthèses pédagogiques ATLAS, avec source officielle de chaque étape.</p></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/trigeminal-neuralgia","label":"Radiopaedia : Trigeminal neuralgia"},{"href":"https://radiopaedia.org/articles/trigeminal-nerve","label":"Radiopaedia : Trigeminal nerve"},{"href":"https://radiopaedia.org/articles/occipital-neuralgia","label":"Radiopaedia : Occipital neuralgia (Arnold)"},{"href":"https://anatomie-fmpm.uca.ma/wp-content/uploads/2020/08/Innervation-de-la-face-et-du-cou.pdf","label":"FMPM — Innervation face & cou (PDF)"}]},{"id":"100-2","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les principales causes de céphalées nécessitant une prise en charge en urgence et leur présentation clinique","contenu":"<div class=\"notion-course\"><h4>Les alertes qui imposent une évaluation urgente</h4><table><thead><tr><th>Présentation</th><th>Cause à rechercher en priorité</th></tr></thead><tbody><tr><td>Coup de tonnerre, avec ou sans raideur de nuque/perte de connaissance</td><td>Hémorragie sous-arachnoïdienne (<span class=\"nc-red_bg\">HSA</span>) ; également SVCR, <span class=\"nc-red nc-bold\">dissection</span> ou autre cause vasculaire.</td></tr><tr><td>Fièvre, méningisme, purpura ou altération de conscience</td><td><span class=\"nc-pink_bg\">Méningite</span>, méningoencéphalite ; sepsis avec purpura : traitement immédiat.</td></tr><tr><td>Déficit focal <span class=\"nc-red nc-bold\">brutal</span>, diplopie, crise épileptique ou confusion</td><td>AVC, <span class=\"nc-red_bg\">thrombose veineuse cérébrale</span> (TVC), processus expansif, infection.</td></tr><tr><td>Progression, <span class=\"nc-blue_bg\">vomissements</span>, trouble visuel, œdème papillaire</td><td>Hypertension intracrânienne (HTIC) : masse, hydrocéphalie ou TVC.</td></tr><tr><td><span class=\"nc-blue_bg\">Cervicalgie</span> et syndrome de Claude Bernard-Horner</td><td><span class=\"nc-red nc-bold\">Dissection</span> carotidienne ; <span class=\"nc-blue_bg\">cervicalgie</span> avec signes postérieurs : <span class=\"nc-red nc-bold\">dissection</span> vertébrale.</td></tr><tr><td>Après 50 ans : claudication de la mâchoire, douleur temporale, baisse visuelle</td><td>Artérite à cellules géantes ; urgence thérapeutique si menace visuelle.</td></tr><tr><td>Œil rouge douloureux, baisse visuelle, <span class=\"nc-blue_bg\">nausées</span></td><td>Glaucome aigu par fermeture de l’angle : urgence ophtalmologique.</td></tr><tr><td><span class=\"nc-red_bg\">Post-partum</span> ou grossesse, HTA, troubles visuels/crises</td><td>Prééclampsie/éclampsie, PRES, TVC, SVCR ; ne pas attribuer automatiquement à une péridurale.</td></tr><tr><td>Plusieurs personnes malades dans un local chauffé</td><td><span class=\"nc-orange\">Intoxication</span> au monoxyde de carbone : mise en sécurité et secours.</td></tr><tr><td>Coup de tonnerre, ophtalmoplégie, déficit bitemporal et hypotension</td><td>Apoplexie hypophysaire avec possible insuffisance corticotrope aiguë.</td></tr></tbody></table><ul><li>Rechercher aussi traumatisme, anticoagulant, cancer, <span class=\"nc-orange\">immunodépression</span> et modification d’une céphalée ancienne.</li><li>Appel du 15 devant menace vitale, trouble de conscience, déficit <span class=\"nc-red nc-bold\">brutal</span> ou céphalée explosive. Le soulagement par un antalgique ne rassure pas sur la cause.</li><li>Un symptôme isolé peut être révélateur : HSA et TVC peuvent débuter par une céphalée sans déficit.</li></ul><div class=\"callout\"><p>Une céphalée habituelle qui change de profil redevient une céphalée à explorer.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p></p></details>","frequence":2},{"id":"100-3","rang":"A","rubrique":"Étiologies","titre":"Énoncer les principales causes de céphalée aiguë et les caractéristiques cliniques propres à chacune","contenu":"<div class=\"notion-course\"><h4>Orienter selon le début et le contexte</h4><table><thead><tr><th>Profil</th><th>Hypothèses et examens orientés</th></tr></thead><tbody><tr><td><span class=\"nc-red nc-bold\">Brutal</span></td><td><span class=\"nc-red_bg\">HSA</span>, SVCR, <span class=\"nc-red nc-bold\">dissection</span>, AVC, TVC, apoplexie hypophysaire. Imagerie cérébrale et vasculaire urgente adaptée ; scanner normal n’élimine pas ces causes.</td></tr><tr><td><span class=\"nc-blue\">Fébrile</span></td><td><span class=\"nc-pink_bg\">Méningite</span>, encéphalite, abcès ou infection générale. Ponction lombaire (PL) si indiquée et sûre ; ne pas retarder un traitement anti-infectieux urgent.</td></tr><tr><td><span class=\"nc-red nc-bold\">Progressif</span></td><td>HTIC, tumeur, hydrocéphalie, TVC, infection, artérite à cellules géantes ; imagerie et bilan guidés par l’examen.</td></tr><tr><td>Orthostatique, surtout après ponction durale</td><td>Hypotension intracrânienne par fuite de LCS ; amélioration <span class=\"nc-green_bg\">en décubitus</span>. Une forme spontanée existe.</td></tr><tr><td>Contexte général ou local</td><td>CO, médicament vasodilatateur, sevrage, trouble métabolique, cause oculaire/ORL/dentaire ; éviter de conclure à une sinusite sur une céphalée <span class=\"nc-red\">inhabituelle</span> isolée.</td></tr></tbody></table><h4>Syndrome de vasoconstriction cérébrale réversible</h4><ul><li>Céphalées en coup de tonnerre récidivant sur une à trois semaines ; parfois déclenchées par <span class=\"nc-red nc-bold\">effort</span>, <span class=\"nc-red nc-bold\">Valsalva</span> ou <span class=\"nc-red nc-bold\">activité sexuelle</span>. Contexte possible : <span class=\"nc-red_bg\">post-partum</span>, <span class=\"nc-red nc-bold\">cannabis</span>, <span class=\"nc-pink nc-bold\">décongestionnants</span>, médicaments <span class=\"nc-pink nc-bold\">sérotoninergiques</span> ou autres substances vasoactives.</li><li><span class=\"nc-blue_bg\">Angio-TDM</span>/angio-IRM : rétrécissements artériels multifocaux. L’examen peut être normal très tôt ; une exploration répétée est décidée si la suspicion persiste. Réversibilité en quelques mois.</li><li>Complications : infarctus, HSA corticale ou hémorragie intracérébrale. Avis spécialisé, arrêt des facteurs déclenchants et surveillance ; un anticalcique peut être discuté, sans preuve qu’il prévient toutes les complications.</li></ul><h4>Hypotension intracrânienne</h4><ul><li>Douleur majorée <span class=\"nc-red nc-bold\">debout</span>/<span class=\"nc-red nc-bold\">assise</span>, soulagée couchée ; parfois <span class=\"nc-blue_bg\">cervicalgie</span>, symptômes auditifs, <span class=\"nc-blue_bg\">nausées</span> ou diplopie par atteinte du VI. Le délai de soulagement varie.</li><li>Après geste dural typique, le diagnostic peut être clinique. Si spontanée, atypique ou compliquée : IRM à la recherche notamment d’un rehaussement pachyméningé diffus et d’un affaissement encéphalique ; exploration de la fuite selon avis spécialisé.</li><li>Avis anesthésique/neurologique ; <span class=\"nc-pink_bg\">blood patch épidural</span> selon gravité et persistance. Une douleur devenue permanente ou un déficit nouveau fait rechercher TVC ou <span class=\"nc-red nc-bold\">hématome sous-dural</span>.</li></ul><div class=\"callout\"><p>Il n’existe pas de frontière fiable à trois heures rendant un infarctus obligatoirement visible au scanner.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p>Correction des faux seuils radiologiques et des formulations absolues sur l’hypotension intracrânienne.</p></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/spontaneous-intracranial-hypotension-2","label":"Radiopaedia : Spontaneous intracranial hypotension"}]},{"id":"100-4","rang":"B","rubrique":"Étiologies","titre":"Énoncer les principales causes de céphalée chronique (épisodique ou quotidienne) et les caractéristiques cliniques propres à chacune","contenu":"<div class=\"notion-course\"><h4>Distinguer ancienneté, fréquence et durée des crises</h4><table><thead><tr><th>Tableau</th><th>Repères</th></tr></thead><tbody><tr><td><span class=\"nc-green_bg\">Migraine épisodique</span></td><td>Crises de 4–72 h chez l’adulte, handicap, aggravation par l’activité ; <span class=\"nc-blue_bg\">nausées</span> et/ou photo-phonophobie. Moins de 15 jours de céphalée par mois.</td></tr><tr><td>Céphalée de tension</td><td>Souvent bilatérale, pression/serrement, <span class=\"nc-green_bg\">légère à modérée</span>, sans aggravation par activité ordinaire ; pas de <span class=\"nc-blue_bg\">vomissements</span>. Épisodique : 30 min à 7 jours, sans <span class=\"nc-blue_bg\">nausées</span> et au plus photophobie ou phonophobie.</td></tr><tr><td><span class=\"nc-yellow_bg\">Céphalée chronique</span> quotidienne</td><td>Au moins 15 jours par mois depuis plus de 3 mois ; description de fréquence, non diagnostic étiologique.</td></tr><tr><td><span class=\"nc-orange_bg\">Migraine chronique</span></td><td>Au moins 15 jours de céphalée par mois dont au moins 8 avec caractères migraineux, pendant plus de 3 mois.</td></tr><tr><td>AVF</td><td>Accès strictement unilatéraux de 15–180 min, signes autonomiques homolatéraux et <span class=\"nc-brown_bg\">agitation</span>. Forme chronique : ≥ 1 an sans rémission ou avec rémissions &lt; 3 mois.</td></tr><tr><td><span class=\"nc-orange_bg\">Névralgie du trijumeau</span></td><td>Décharges de quelques secondes à 2 min, territoire d’une branche du V et déclenchement par stimulus anodin.</td></tr></tbody></table><h4>Rechercher un abus médicamenteux</h4><p>Céphalée <span class=\"nc-pink_bg\">≥ 15 jours/mois</span> chez un sujet ayant une céphalée préexistante et surconsommation régulière pendant plus de 3 mois :</p><ul><li>Seuil ≥ 15 jours/mois pour antalgiques simples non opioïdes (<span class=\"nc-pink_bg\">paracétamol</span>, aspirine, AINS).</li><li>Seuil ≥ 10 jours/mois pour <span class=\"nc-pink nc-bold\">triptans</span>, opioïdes, dérivés ergotés ou associations antalgiques ; prendre en compte le cumul des classes.</li><li>Compter les jours de prise, et non le nombre de comprimés. Les prises pour une autre douleur comptent aussi.</li><li><span class=\"nc-orange_bg\">Migraine chronique</span> et abus peuvent coexister ; l’amélioration après sevrage n’est pas exigée avant de reconnaître l’abus.</li></ul><h4>Ne pas oublier une cause secondaire chronique</h4><ul><li>Céphalée post-traumatique, lésion intracrânienne, HTIC, fuite de LCS, affection locale ou toxique selon contexte.</li><li>Interroger sur les débuts : une céphalée devenue quotidienne dès son apparition n’a pas le même profil qu’une migraine progressivement plus fréquente.</li><li>Agenda des jours douloureux, traitement, règles, sommeil et retentissement ; examen et imagerie selon signes d’alerte et phénotype. Une migraine typique stable sans alerte n’exige pas une imagerie systématique.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p>Correction de la définition de l’AVF chronique ; distinction entre CCQ, migraine chronique et abus.</p></details>","frequence":1},{"id":"100-5","rang":"A","rubrique":"Étiologies","titre":"Énoncer les principales causes des céphalées récentes d’aggravation progressive et les caractéristiques cliniques propres à chacune","contenu":"<div class=\"notion-course\"><h4>Une céphalée <span class=\"nc-red\">récente</span> qui s’intensifie exige une cause</h4><table><thead><tr><th>Cause</th><th>Indices cliniques et démarche</th></tr></thead><tbody><tr><td>Processus expansif / hydrocéphalie</td><td><span class=\"nc-blue_bg\">Vomissements</span>, aggravation au <span class=\"nc-red nc-bold\">Valsalva</span> ou au décubitus, déficit, œdème papillaire, troubles de vigilance ; imagerie cérébrale. Pas de PL avant exclusion d’un obstacle/effet de masse.</td></tr><tr><td>TVC</td><td>Terrain prothrombotique, grossesse/<span class=\"nc-red_bg\">post-partum</span>, contraception œstroprogestative ; céphalée parfois seule, HTIC, <span class=\"nc-yellow_bg\">crises</span> ou déficit. Imagerie veineuse indispensable si suspicion.</td></tr><tr><td><span class=\"nc-pink_bg\">Méningite</span> subaiguë, carcinomatose méningée</td><td>Fièvre parfois discrète, <span class=\"nc-orange\">immunodépression</span>, cancer, atteinte de nerfs crâniens ; bilan infectieux/néoplasique, imagerie et LCS selon sécurité.</td></tr><tr><td>Artérite à cellules géantes</td><td>Après 50 ans, douleur nouvelle, hypersensibilité du cuir chevelu, mâchoire à l’<span class=\"nc-red nc-bold\">effort</span>, signes généraux ou visuels. CRP/NFS et filière urgente.</td></tr><tr><td>HTIC idiopathique</td><td>Souvent femme jeune avec obésité, <span class=\"nc-orange_bg\">céphalées</span>, éclipses visuelles, acouphènes pulsatiles, œdème papillaire. Diagnostic après exclusion masse/TVC ; pression d’ouverture du LCS et composition <span class=\"nc-green_bg\">normale</span>.</td></tr><tr><td>Hypotension intracrânienne</td><td>Caractère postural, geste dural ou fuite spontanée ; IRM si non typique ou persistante.</td></tr><tr><td>Causes générales/locales</td><td>CO, médicaments, infection ORL, trouble ophtalmologique, apnées du <span class=\"nc-green_bg\">sommeil</span> selon contexte ; ne pas les retenir avant d’avoir évalué les alertes.</td></tr></tbody></table><div class=\"callout\"><p>Chez l’enfant : <span class=\"nc-blue_bg\">vomissements</span> matinaux, anomalie neurologique, modification du comportement/croissance ou trouble endocrinien central orientent le bilan. Le seul caractère chronique ne rassure pas.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941815190d2cd56ce0037d7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées chez l’enfant (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p></p></details>","frequence":1},{"id":"100-6","rang":"A","rubrique":"Identifier une urgence","titre":"Discuter l’indication d’une hospitalisation et d’une ponction lombaire devant une céphalée aiguë en connaissant la pertinence de cet examen","contenu":"<div class=\"notion-course\"><h4>Hospitaliser selon le risque et la possibilité de surveillance</h4><ul><li>Cause grave suspectée, trouble de conscience, déficit focal, syndrome méningé, HTIC, grossesse/<span class=\"nc-red_bg\">post-partum</span> à risque ou état général altéré.</li><li>Douleur/<span class=\"nc-blue_bg\">vomissements</span> incontrôlables, déshydratation, impossibilité d’explorer ou de surveiller rapidement ; ne pas renvoyer sans consignes un bilan incomplet.</li></ul><h4>Ce que la ponction lombaire peut apporter</h4><table><thead><tr><th>Question</th><th>Utilité</th></tr></thead><tbody><tr><td><span class=\"nc-pink_bg\">Méningite</span> / encéphalite ?</td><td>Cytologie, protéines, glucose avec glycémie concomitante, microbiologie adaptée. Traitement probabiliste immédiat si la PL est retardée et infection grave suspectée.</td></tr><tr><td>HSA malgré imagerie initiale négative ?</td><td>Recherche de sang et produits de dégradation selon délai et protocole du laboratoire. Une imagerie négative ne clôt pas une forte suspicion.</td></tr><tr><td>HTIC idiopathique ?</td><td>Mesure de pression d’ouverture <span class=\"nc-green_bg\">en décubitus</span> et analyse du LCS, après imagerie cérébrale/veineuse excluant cause secondaire et contre-indication.</td></tr><tr><td>Inflammation / atteinte méningée néoplasique ?</td><td>Examens ciblés sur hypothèse clinique, éventuellement cytologie et prélèvements répétés.</td></tr></tbody></table><h4>Avant de piquer</h4><ol><li>Rechercher signes d’engagement, lésion expansive ou hydrocéphalie obstructive : imagerie prioritaire si suspicion.</li><li>Vérifier hémostase, traitements anticoagulants, infection du point de ponction et stabilité cardiorespiratoire ; corriger ou différer si nécessaire.</li><li>Dans la suspicion de <span class=\"nc-pink_bg\">méningite</span>, l’imagerie préalable dépend des signes de complication et contre-indication ; elle ne doit pas devenir une formalité qui retarde l’antibiothérapie.</li><li>Interpréter le LCS avec le contexte et le délai. Un scanner normal ne garantit pas à lui seul que la PL est sûre.</li></ol><div class=\"callout\"><p>HTIC par masse/obstacle et HTIC idiopathique n’ont pas la même conduite vis-à-vis de la PL. Ne pas écrire « toute HTIC interdit toute PL ».</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941815190d2cd56ce0037d7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées chez l’enfant (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p></p></details>","frequence":0},{"id":"100-7","rang":"A","rubrique":"Prise en charge","titre":"Savoir mettre en route un traitement des céphalées aux urgences","contenu":"<div class=\"notion-course\"><h4>Soulager tout en recherchant la cause</h4><ol><li>Évaluer ABC, conscience, constantes, déficit, purpura et douleur ; installer au calme, voie veineuse et surveillance si nécessaire.</li><li>Donner une antalgie adaptée (<span class=\"nc-pink_bg\">paracétamol</span> notamment) et un antiémétique selon terrain ; corriger une déshydratation. Éviter une sédation masquant la surveillance.</li><li>Tant qu’une hémorragie n’est pas exclue, éviter aspirine et AINS. Ne pas utiliser un triptan pour une <span class=\"nc-yellow_bg nc-bold\">céphalée secondaire</span> possible, notamment un SVCR.</li><li>Lancer en parallèle imagerie, biologie et/ou PL selon tableau ; avis spécialisé et traitement étiologique sans attendre inutilement tous les résultats.</li></ol><table><thead><tr><th>Cause</th><th>Priorité thérapeutique</th></tr></thead><tbody><tr><td><span class=\"nc-pink_bg\">Méningite</span> bactérienne suspectée</td><td>Antibiothérapie probabiliste urgente selon protocole ; dexaméthasone selon indication.</td></tr><tr><td>HSA / hydrocéphalie menaçante</td><td>Filière neurovasculaire/neurochirurgicale et protection des fonctions vitales.</td></tr><tr><td>TVC</td><td>Anticoagulation et avis spécialisé selon diagnostic et contexte.</td></tr><tr><td>Artérite à cellules géantes avec menace visuelle</td><td><span class=\"nc-pink_bg nc-bold\">Corticothérapie</span> urgente ; ne pas attendre la confirmation histologique.</td></tr><tr><td>CO / glaucome aigu / éclampsie</td><td>Traitement immédiat propre à la cause, avec filière dédiée.</td></tr></tbody></table><h4>Si une crise primaire habituelle est retenue</h4><ul><li>Traitement de crise spécifique, voie adaptée aux <span class=\"nc-blue_bg\">vomissements</span> et contre-indications. <span class=\"nc-blue_bg\">Migraine</span> : AINS ou triptan selon plan ; AVF : oxygène et/ou sumatriptan selon indication.</li><li>Réévaluer après traitement. Une persistance <span class=\"nc-red\">inhabituelle</span> impose de réexaminer le diagnostic.</li><li>À la sortie : plan écrit, limite des jours de prise, suivi et signes imposant un retour urgent ; ne pas banaliser une douleur parce qu’elle a cédé.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941815190d2cd56ce0037d7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées chez l’enfant (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p></p></details>","frequence":0},{"id":"100-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication et la pertinence de l’imagerie devant une céphalée aiguë et chronique chez l’adulte et l’enfant","contenu":"<div class=\"notion-course\"><h4>Adulte : choisir l’examen qui répond à l’hypothèse</h4><table><thead><tr><th>Présentation</th><th>Exploration</th></tr></thead><tbody><tr><td>Coup de tonnerre</td><td><span class=\"nc-blue_bg\">TDM cérébrale sans injection</span> en urgence, avec exploration vasculaire selon suspicion. Si négative et suspicion persistante : poursuite du bilan (PL et/ou imagerie complémentaire) selon délai, qualité du scanner et avis spécialisé.</td></tr><tr><td>Progression / déficit / HTIC / terrain à risque</td><td>IRM souvent la plus informative ; TDM si plus immédiatement disponible et nécessaire. Ajouter exploration veineuse pour TVC, artérielle pour <span class=\"nc-red nc-bold\">dissection</span>/anévrisme.</td></tr><tr><td>SVCR possible, premier bilan normal</td><td>Réévaluation et angiographie répétée selon avis ; la première exploration peut être trop précoce.</td></tr><tr><td><span class=\"nc-blue_bg\">Migraine</span> typique stable, examen normal, aucune alerte</td><td>Pas d’imagerie systématique. IRM si atypies, aura <span class=\"nc-red\">inhabituelle</span>, nouveau profil ou autre indication clinique.</td></tr></tbody></table><h4>Enfant : adapter aussi le délai</h4><p>La HAS distingue le besoin d’imagerie et son urgence ; son arbre ne couvre pas le traumatisme aigu ni la suspicion de <span class=\"nc-pink_bg\">méningite</span>, qui suivent leurs propres parcours.</p><table><thead><tr><th>Situation</th><th>Orientation HAS</th></tr></thead><tbody><tr><td>Coup de tonnerre, conscience altérée, déficit <span class=\"nc-red nc-bold\">brutal</span>/<span class=\"nc-blue\">fébrile</span>, HTIC menaçante</td><td>Appel du 15 ; imagerie sans délai.</td></tr><tr><td>HTIC sans signe de menace immédiate</td><td>Imagerie dans les 24–72 h, avec surveillance et consignes.</td></tr><tr><td>Anomalie neurologique progressive non <span class=\"nc-blue\">fébrile</span></td><td>Imagerie dans la semaine.</td></tr><tr><td>Céphalée nouvelle continue croissante ou trouble endocrinien central</td><td>Imagerie dans le mois ; dans les 15 jours si diabète insipide.</td></tr><tr><td>Absence de drapeau rouge, examen rassurant</td><td>Pas d’imagerie de routine ; suivi clinique. Céphalée occipitale d’<span class=\"nc-red nc-bold\">effort</span> reproductible : envisager une anomalie de charnière et une <span class=\"nc-blue_bg\">IRM</span>.</td></tr></tbody></table><p>L’IRM est privilégiée lorsqu’une imagerie programmée est indiquée ; en urgence, choisir l’examen immédiatement adapté sans retarder la prise en charge. Les délais du tableau sont des maxima, à raccourcir si aggravation.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941815190d2cd56ce0037d7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées chez l’enfant (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/2024-01/app480_arbre_decisionnel_mg_cephalee_cd_2023_12_14.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Céphalées de l’enfant : arbre pour les médecins, décembre 2023</a></li><li><a href=\"https://www.has-sante.fr/upload/docs/application/pdf/2024-01/app480_arbre_decisionnel_radiologues_cephalee_cd_2023_12_14.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Céphalées de l’enfant : modalités de l’imagerie</a></li></ul><p>L’arbre interactif pédiatrique reprend les catégories de délai de la HAS. Suppression de l’injection scanographique systématique chez l’enfant.</p></details>","frequence":3},{"id":"100-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de traitement et de prise en charge des céphalées primaires en dehors du contexte de l’urgence","contenu":"<div class=\"notion-course\"><h4>Une stratégie au-delà de l’antalgique</h4><ol><li>Confirmer le phénotype et expliquer le diagnostic ; rechercher abus, comorbidités anxieuses/dépressives et retentissement.</li><li>Tenir un agenda simple des jours de douleur et de prise ; individualiser <span class=\"nc-green_bg\">sommeil</span>, repas, activité physique et facteurs déclenchants reproductibles.</li><li>Donner un plan de crise efficace et préciser quand le prendre, les contre-indications et les limites mensuelles.</li><li>Discuter un traitement préventif si fréquence/handicap important, traitement de crise insuffisant ou surconsommation ; évaluer efficacité et tolérance au suivi.</li></ol><table><thead><tr><th>Type</th><th>Principes</th></tr></thead><tbody><tr><td><span class=\"nc-blue_bg\">Migraine</span></td><td>Traitement de crise adapté, puis prévention selon handicap et terrain ; voir item 99.</td></tr><tr><td>Tension</td><td>Antalgique simple ponctuel ; prise en charge des facteurs musculaires et du <span class=\"nc-red_bg\">stress</span>, activité physique ; <span class=\"nc-pink\">amitriptyline</span> possible dans <span class=\"nc-blue_bg\">formes</span> chroniques selon avis.</td></tr><tr><td>AVF</td><td>Filière spécialisée, traitement de crise rapide et prévention ; ne pas appliquer la stratégie de <span class=\"nc-blue_bg\">migraine</span>.</td></tr><tr><td>Abus médicamenteux</td><td>Expliquer le mécanisme, organiser réduction/sevrage et prévention. Opioïdes ou dépendance : accompagnement spécifique, parfois hospitalier.</td></tr><tr><td>Enfant</td><td>Explications adaptées à la famille, retentissement scolaire, rythme régulier ; traitement dosé au poids et surveillance. Les stratégies préventives sont individualisées.</td></tr></tbody></table><div class=\"callout\"><p>Prévoir une réévaluation si changement de type, déficit, fièvre, aggravation ou traitement devenu inefficace.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 13 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées (100)</a></li><li><a href=\"https://app.notion.com/p/2ad37f85d941815190d2cd56ce0037d7?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Céphalées chez l’enfant (100)</a></li><li><a href=\"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant\" target=\"_blank\" rel=\"noopener noreferrer\">CEN · Item 100, chapitre 11</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Le scanner normal ne clôt pas le bilan","contenu":"<div class=\"notion-course\"><p><span class=\"nc-red_bg\">HSA</span>, TVC, <span class=\"nc-red nc-bold\">dissection</span> ou SVCR peuvent demander des examens supplémentaires.</p></div>"},{"type":"piege","titre":"Ancienne ne signifie pas bénigne","contenu":"<div class=\"notion-course\"><p>Toute modification <span class=\"nc-red\">récente</span> d’une céphalée connue impose de reconsidérer sa cause.</p></div>"}],"strategie":{"urgence":"<div class=\"notion-course\"><ul><li>Coup de tonnerre, fièvre avec signes <span class=\"nc-purple_bg\">méningés</span>, déficit, conscience altérée ou menace visuelle : évaluation immédiate.</li></ul></div>","hospit":"<div class=\"notion-course\"><ul><li>Hospitaliser si cause grave suspectée, bilan urgent non réalisable ou surveillance/traitement nécessaires.</li></ul></div>","redflags":"<div class=\"notion-course\"><ul><li>Nouveau profil, aggravation, cancer, <span class=\"nc-orange\">immunodépression</span>, grossesse/<span class=\"nc-red_bg\">post-partum</span>, anomalie neurologique ou papillaire.</li></ul></div>","principes":"<div class=\"notion-course\"><ul><li>Dater le début ; examiner ; choisir l’imagerie et la PL selon hypothèse ; soulager en parallèle.</li></ul></div>","suivi":"<div class=\"notion-course\"><ul><li>Agenda, prévention de l’abus, plan de crise et consignes de réévaluation.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.cen-neurologie.fr/second-cycle/i-connaissances/chapitre-11-item-100-cephalee-inhabituelle-aigue-et-chronique-chez-ladulte-et-lenfant","label":"CEN · Item 100, chapitre 11 ↗"},{"href":"https://www.has-sante.fr/upload/docs/application/pdf/2024-01/app480_arbre_decisionnel_mg_cephalee_cd_2023_12_14.pdf","label":"HAS · Céphalées de l’enfant : arbre pour les médecins, décembre 2023 ↗"},{"href":"https://www.has-sante.fr/upload/docs/application/pdf/2024-01/app480_arbre_decisionnel_radiologues_cephalee_cd_2023_12_14.pdf","label":"HAS · Céphalées de l’enfant : modalités de l’imagerie ↗"},{"href":"https://livret.uness.fr/lisa/2026/C%C3%A9phal%C3%A9e_SDD-118","label":"LiSA · SDD 118 — Céphalée ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Comment la douleur a-t-elle commencé ?","detail":"<ul><li>Dater le maximum, rechercher fièvre, déficit, grossesse et terrain.</li><li>Examiner conscience, neurologie, méningisme, œil et pression artérielle.</li></ul>","branches":[{"label":"Coup de tonnerre / alerte majeure","to":"urgence"},{"label":"Progressive ou inhabituelle sans détresse","to":"progressive"},{"label":"Profil ancien strictement inchangé","to":"primaire"}]},{"id":"urgence","kind":"urgent","label":"Évaluation hospitalière immédiate","detail":"<ul><li>Rechercher hémorragie, infection, cause vasculaire ou oculaire.</li><li>Imagerie urgente adaptée ; antalgie et traitement causal en parallèle.</li></ul>","branches":[{"label":"Suspicion HSA malgré bilan initial négatif","to":"hsa"},{"label":"Syndrome infectieux/méningé","to":"infection"},{"label":"Déficit, œil, HTIC ou autre orientation","to":"cible"}]},{"id":"hsa","kind":"urgent","label":"Un premier scanner négatif ne clôt pas tout bilan","detail":"<ul><li>Interpréter délai, qualité et expertise de l’imagerie.</li><li>Discuter PL et/ou exploration vasculaire selon protocole neurovasculaire.</li><li>Ne pas retarder la prise en charge d’une HSA confirmée pour une PL inutile. SVCR, dissection et thrombose veineuse restent des alternatives selon contexte.</li></ul>","branches":[]},{"id":"infection","kind":"urgent","label":"Méningite possible : traiter sans retard indu","detail":"<ul><li>Hémocultures et PL si immédiatement possible et sûre.</li><li>Si PL différée ou contre-indiquée, ne pas retarder antibiothérapie indiquée.</li><li>Imagerie préalable uniquement lorsqu’indiquée. Rechercher risque d’engagement, trouble hémostatique et infection locale avant PL.</li></ul>","branches":[]},{"id":"cible","kind":"urgent","label":"Explorer l’hypothèse menaçante","detail":"<ul><li>Angio-imagerie artérielle/veineuse, IRM ou bilan ophtalmologique selon signes.</li><li>Après 50 ans, rechercher artérite à cellules géantes ; grossesse/post-partum : causes spécifiques.</li></ul>","branches":[]},{"id":"progressive","kind":"decision","label":"Y a-t-il une cause secondaire plausible ?","detail":"<ul><li>Rechercher réveils, vomissements, posture, effort et aggravation.</li><li>Adapter délai d’IRM et examen ophtalmologique au risque.</li></ul>","branches":[{"label":"Atypie, terrain ou examen anormal","to":"bilan"},{"label":"Examen normal et profil primaire cohérent","to":"primaire"},{"label":"Informations insuffisantes","to":"doute"}]},{"id":"bilan","kind":"finish","label":"Organiser les explorations ciblées","detail":"<ul><li>Choisir imagerie et avis selon la suspicion.</li><li>Ne pas proposer de PL sans évaluer ses contre-indications.</li></ul>","branches":[]},{"id":"primaire","kind":"finish","label":"Confirmer un diagnostic positif de céphalée primaire","detail":"<ul><li>Critères, fréquence, médicaments et retentissement.</li><li>Suivre le parcours chronique et les traitements spécifiques.</li></ul>","branches":[]},{"id":"doute","kind":"uncertain","label":"Reprendre l’évaluation et fixer un délai sûr","detail":"<ul><li>Compléter anamnèse/examen, avis si nécessaire.</li><li>Donner les signes d’adressage immédiat.</li></ul>","branches":[]}]},"cards":[{"i":"095eace36d64","n":100,"o":"100-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une céphalée aiguë et d’une céphalée chronique","q":"Une céphalée récente dure depuis dix jours. Ce délai permet-il d’écarter une cause secondaire ?","a":"<div class=\"notion-course\"><ul><li>Non : le caractère nouveau, <span class=\"nc-red nc-bold\">inhabituel</span> et l’évolution comptent.</li><li>Sept jours n’est pas une limite de sécurité.</li></ul></div>"},{"i":"d4d82b727ea5","n":100,"o":"100-1","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une céphalée aiguë et d’une céphalée chronique","q":"Une céphalée très brutale atteint son maximum en 30 secondes. Comment la qualifier ?","a":"<div class=\"notion-course\"><ul><li>Céphalée en coup de tonnerre.</li><li>Exploration urgente, notamment pour HSA.</li></ul></div>"},{"i":"43d46257ebba","n":100,"o":"100-2","u":"Identifier une urgence","t":"Connaître les principales causes de céphalées nécessitant une prise en charge en urgence et leur présentation clinique","q":"Une migraineuse présente une douleur différente avec diplopie. Quelle priorité ?","a":"<div class=\"notion-course\"><ul><li>Rechercher une cause secondaire urgente.</li><li>Un antécédent de migraine n’explique pas automatiquement un nouveau tableau.</li></ul></div>"},{"i":"75ac26de2e0f","n":100,"o":"100-2","u":"Identifier une urgence","t":"Connaître les principales causes de céphalées nécessitant une prise en charge en urgence et leur présentation clinique","q":"Céphalée et nausées chez plusieurs personnes d’un logement chauffé : quelle cause évoquer ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-orange\">Intoxication</span> au monoxyde de carbone.</li><li>Mise en sécurité et appel des secours.</li></ul></div>"},{"i":"5dd3f4e46064","n":100,"o":"100-3","u":"Étiologies","t":"Énoncer les principales causes de céphalée aiguë et les caractéristiques cliniques propres à chacune","q":"Des coups de tonnerre récidivent pendant deux semaines, mais l’angiographie initiale était normale. Quelle hypothèse reste possible ?","a":"<div class=\"notion-course\"><ul><li>Syndrome de vasoconstriction cérébrale réversible.</li><li>L’imagerie vasculaire peut être <span class=\"nc-green_bg\">normale</span> au début ; réévaluation spécialisée.</li></ul></div>"},{"i":"4fccfd80fe11","n":100,"o":"100-3","u":"Étiologies","t":"Énoncer les principales causes de céphalée aiguë et les caractéristiques cliniques propres à chacune","q":"Une céphalée après PL, calmée couchée, devient permanente avec déficit. Que rechercher ?","a":"<div class=\"notion-course\"><ul><li>Complication, notamment <span class=\"nc-red nc-bold\">hématome sous-dural</span> ou TVC.</li><li>Réévaluation et imagerie urgentes.</li></ul></div>"},{"i":"e98a6709bcd6","n":100,"o":"100-4","u":"Étiologies","t":"Énoncer les principales causes de céphalée chronique (épisodique ou quotidienne) et les caractéristiques cliniques propres à chacune","q":"Quel seuil définit une céphalée chronique quotidienne ?","a":"<div class=\"notion-course\"><ul><li>Au moins 15 jours de céphalée par mois depuis plus de 3 mois.</li><li>C’est une fréquence, pas une cause.</li></ul></div>"},{"i":"28b7d6f61f67","n":100,"o":"100-4","u":"Étiologies","t":"Énoncer les principales causes de céphalée chronique (épisodique ou quotidienne) et les caractéristiques cliniques propres à chacune","q":"Migraine et triptan 12 jours/mois depuis quatre mois : quel seuil d’abus est dépassé ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-pink nc-bold\">Triptans</span> : au moins 10 jours/mois pendant plus de 3 mois.</li><li>Pour diagnostiquer la céphalée par abus, vérifier aussi ≥ 15 jours de céphalée/mois.</li></ul></div>"},{"i":"0690d904eded","n":100,"o":"100-4","u":"Étiologies","t":"Énoncer les principales causes de céphalée chronique (épisodique ou quotidienne) et les caractéristiques cliniques propres à chacune","q":"Comment se définit une AVF chronique ?","a":"<div class=\"notion-course\"><ul><li>Évolution ≥ 1 an sans rémission ou avec des rémissions de moins de 3 mois.</li></ul></div>"},{"i":"79d93772d096","n":100,"o":"100-5","u":"Étiologies","t":"Énoncer les principales causes des céphalées récentes d’aggravation progressive et les caractéristiques cliniques propres à chacune","q":"Céphalée progressive, œdème papillaire et contraception œstroprogestative : quelle exploration ne pas oublier ?","a":"<div class=\"notion-course\"><ul><li>Imagerie veineuse cérébrale à la recherche d’une TVC.</li></ul></div>"},{"i":"78c1c616301d","n":100,"o":"100-6","u":"Identifier une urgence","t":"Discuter l’indication d’une hospitalisation et d’une ponction lombaire devant une céphalée aiguë en connaissant la pertinence de cet examen","q":"Une PL est-elle interdite dans toute HTIC ?","a":"<div class=\"notion-course\"><ul><li>Non. Elle est dangereuse en cas de masse/obstacle avec risque d’engagement.</li><li>Dans une HTIC idiopathique suspectée, elle mesure la pression après imagerie et vérification des contre-indications.</li></ul></div>"},{"i":"2cdc062ff64d","n":100,"o":"100-6","u":"Identifier une urgence","t":"Discuter l’indication d’une hospitalisation et d’une ponction lombaire devant une céphalée aiguë en connaissant la pertinence de cet examen","q":"Une suspicion de méningite grave nécessite une imagerie avant la PL. Faut-il attendre pour traiter ?","a":"<div class=\"notion-course\"><ul><li>Non : ne pas retarder l’antibiothérapie urgente à cause du délai d’imagerie ou de PL.</li></ul></div>"},{"i":"5d03a2711b84","n":100,"o":"100-7","u":"Prise en charge","t":"Savoir mettre en route un traitement des céphalées aux urgences","q":"Quels antalgiques éviter devant une céphalée inhabituelle tant qu’une hémorragie est possible ?","a":"<div class=\"notion-course\"><ul><li>Aspirine et AINS.</li><li>Une antalgie adaptée ne doit pas retarder le bilan étiologique.</li></ul></div>"},{"i":"c38d8ed9f2c7","n":100,"o":"100-7","u":"Prise en charge","t":"Savoir mettre en route un traitement des céphalées aux urgences","q":"Une céphalée nouvelle disparaît après antalgique. La cause grave est-elle exclue ?","a":"<div class=\"notion-course\"><ul><li>Non : la réponse antalgique ne remplace pas le bilan indiqué.</li></ul></div>"},{"i":"1223a3a9ddb8","n":100,"o":"100-8","u":"Examens complémentaires","t":"Connaître l’indication et la pertinence de l’imagerie devant une céphalée aiguë et chronique chez l’adulte et l’enfant","q":"Enfant avec céphalée et trouble brutal de conscience : quel délai d’imagerie ?","a":"<div class=\"notion-course\"><ul><li>Sans délai, par une filière urgente ; appel du 15.</li></ul></div>"},{"i":"2f30acada5e3","n":100,"o":"100-8","u":"Examens complémentaires","t":"Connaître l’indication et la pertinence de l’imagerie devant une céphalée aiguë et chronique chez l’adulte et l’enfant","q":"Un enfant migraineux a des crises habituelles et un examen normal, sans alerte. Faut-il une IRM systématique ?","a":"<div class=\"notion-course\"><ul><li>Non. L’indication dépend des drapeaux rouges et du phénotype.</li></ul></div>"},{"i":"dfa12d5f40f0","n":100,"o":"100-9","u":"Prise en charge","t":"Connaître les principes de traitement et de prise en charge des céphalées primaires en dehors du contexte de l’urgence","q":"Que compter dans un agenda de céphalées pour prévenir l’abus ?","a":"<div class=\"notion-course\"><ul><li>Les jours de céphalée et les jours de traitement, pour chaque classe et au total.</li><li>Inclure les antalgiques pris pour d’autres douleurs.</li></ul></div>"},{"i":"91c06ec766fc","n":100,"o":"100-9","u":"Prise en charge","t":"Connaître les principes de traitement et de prise en charge des céphalées primaires en dehors du contexte de l’urgence","q":"Quand discuter une prévention de la migraine ?","a":"<div class=\"notion-course\"><ul><li><span class=\"nc-yellow_bg\">Crises</span> fréquentes ou invalidantes, contrôle insuffisant, traitements de crise limités ou besoin trop fréquent.</li><li>Décision selon handicap, terrain et préférences.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418128b08fd5910917293b?pvs=204","reviewedAt":"2026-10-13","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddVerifiedAt":"2026-10-13","sdd":[{"number":118,"title":"Céphalée","url":"https://livret.uness.fr/lisa/2026/C%C3%A9phal%C3%A9e_SDD-118"}]}};
